// Physical Therapy Practice Test 1. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items: clinical reasoning across conditions and outcome measures.
import {q, mix} from './q.js';
const PAG='Pagliarulo, Introduction to Physical Therapy', PF='Pierson & Fairchild, Principles and Techniques of Patient Care', DHO='Simmers, DHO: Health Science', APTA='APTA';
const PROF='Profession of PT', LEGAL='Legal and Ethical Considerations', MSK='Physical Therapy for Musculoskeletal Conditions', NEURO='Physical Therapy for Neuromuscular Conditions', CP='Physical Therapy for Cardiopulmonary Conditions', INTEG='Physical Therapy for Integumentary Conditions', AGE='Physical Therapy for Pediatrics and Older Adults';

export default {
 id:'physical-therapy-1',
 event:'Physical Therapy',
 title:'Practice Test 1',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'Pagliarulo’s Introduction to Physical Therapy, Pierson & Fairchild’s Principles and Techniques of Patient Care, DHO: Health Science and the APTA',
 plan:[{area:PROF,weight:14},{area:LEGAL,weight:10},{area:MSK,weight:16},{area:NEURO,weight:16},{area:CP,weight:14},{area:INTEG,weight:14},{area:AGE,weight:16}],
 questions:mix([
  q(PROF,'What is the entry-level degree for physical therapists in the United States?','Doctor of Physical Therapy',['Associate degree','Bachelor’s degree','Master’s degree in nursing'],'B','All accredited entry-level PT programs now award the clinical doctorate (DPT). Physical therapist assistants complete an associate degree.',PAG),
  q(PROF,'Which task may a physical therapist assistant NOT perform?','The initial evaluation and plan of care',['Therapeutic exercise from the plan of care','Gait training with an assistive device','Documenting treatment sessions'],'D','The PT performs the initial evaluation, diagnosis, prognosis and plan of care. The PTA carries out interventions under the PT’s direction and supervision.',PAG),
  q(PROF,'What does “direct access” mean in physical therapy?','Patients can see a PT without referral',['PTs can prescribe most medications','Patients go directly to surgery','PTs work only in hospitals'],'A','All U.S. states allow some form of direct access, though some limit the number of visits or require a referral after a period of time.',APTA),
  q(PROF,'Which national organization represents physical therapists, PTAs and students?','APTA',['AOTA','NATA','AMA'],'C','The American Physical Therapy Association sets professional standards, the Code of Ethics and advocacy for the profession. AOTA represents occupational therapy.',APTA),
  q(PROF,'Who is responsible for developing a patient’s physical therapy plan of care?','The physical therapist',['The physical therapist assistant','The PT aide','The patient’s insurer'],'B','The PT examines the patient, sets goals and designs the plan of care. The PTA may provide treatment under it.',PAG),
  q(PROF,'In the ICF model, a stroke survivor who can no longer attend her book club has a restriction in which component?','Participation',['Body structure','Body function','Health condition'],'D','The ICF model describes body functions and structures, activities (tasks) and participation (involvement in life situations), along with environmental and personal factors.',PAG),
  q(PROF,'Evidence-based practice combines which three elements?','Research, clinical expertise, patient values',['Insurance rules, cost and convenience','Tradition, intuition and habit','Physician orders, cost and speed'],'A','Evidence-based practice integrates the best available research with the clinician’s expertise and the patient’s preferences and circumstances.',PAG),
  q(LEGAL,'Before beginning treatment, what must the PT obtain from the patient?','Informed consent',['A signed insurance waiver','A recommendation from family','Payment in full'],'C','Patients must understand the proposed treatment, its risks and benefits and their alternatives, and agree to it.',PF),
  q(LEGAL,'In a SOAP note, where would goniometry measurements and strength grades be recorded?','Objective',['Subjective','Assessment','Plan'],'B','Objective data are measurable findings, such as range of motion, strength and vital signs. Subjective information is what the patient reports.',PF),
  q(LEGAL,'Which action helps protect patient privacy in a busy outpatient clinic?','Using private spaces to discuss care',['Posting the schedule with diagnoses on the wall','Discussing patients in the waiting area','Leaving charts open on the front desk'],'D','HIPAA requires reasonable safeguards to protect health information, such as private spaces and secured records.',PF),
  q(LEGAL,'What may a PT aide do?','Assist with non-skilled tasks under direct supervision',['Independently perform therapeutic exercise','Write the plan of care','Perform the initial evaluation'],'A','Aides help with tasks such as preparing equipment and assisting with transfers, but they cannot independently provide skilled interventions.',PAG),
  q(LEGAL,'A competent patient refuses gait training today. What should the PT do?','Respect it, ask why and document',['Perform the training anyway','Discharge the patient immediately','Ask the family to persuade the patient'],'C','Patients have the right to refuse. The therapist can educate the patient, address concerns and document the refusal.',PF),
  q(MSK,'During a biceps curl, lowering the weight slowly while the muscle lengthens is which type of contraction?','Eccentric',['Concentric','Isometric','Isokinetic'],'B','In an eccentric contraction, the muscle lengthens under tension. In a concentric contraction it shortens, and in an isometric contraction its length does not change.',PF),
  q(MSK,'After a total knee replacement, why is early range-of-motion exercise emphasized?','To prevent stiffness and adhesions',['To strengthen the hip only','To reduce the need for walking','To speed fusion of the bones'],'D','Early knee flexion and extension, sometimes with a continuous passive motion machine, helps prevent adhesions and loss of motion.',PAG),
  q(MSK,'Which exercise approach is commonly used for chronic low back pain?','Core stabilization and general activity',['Strict bed rest for several weeks','Avoiding all movement','Heavy lifting from the first day'],'A','Strengthening trunk muscles and staying active improve function. Prolonged bed rest worsens deconditioning and pain.',PAG),
  q(MSK,'Which exercise is often recommended for patients with knee osteoarthritis?','Low-impact aquatic exercise',['High-impact jumping drills','Complete rest of the joint','Running downhill'],'C','Low-impact exercise strengthens muscles around the joint and maintains motion while limiting joint stress.',PAG),
  q(MSK,'Heel pain that is worst with the first steps in the morning suggests which condition?','Plantar fasciitis',['Achilles rupture','Ankle sprain','Shin splints'],'B','The plantar fascia tightens overnight; the first steps stretch it, causing sharp heel pain. Stretching and footwear changes are common treatments.',PAG),
  q(MSK,'What is the final phase of fracture healing?','Remodeling',['Inflammation','Soft callus formation','Hard callus formation'],'D','Bone heals through inflammation, soft callus, hard callus and finally remodeling, when bone is reshaped according to the stresses placed on it.',PAG),
  q(MSK,'A patient is allowed toe-touch weight bearing on the left leg. What does this mean?','The toes may touch the floor for balance only',['Full weight may be placed on the leg','No contact with the floor is allowed','Weight bearing is limited only by pain'],'A','Toe-touch weight bearing lets the foot rest on the floor for balance without bearing weight. Weight bearing as tolerated is limited only by comfort.',PF),
  q(MSK,'A patient who is non-weight-bearing on one leg uses crutches. Which gait pattern is used?','Three-point gait',['Four-point gait','Two-point gait','Swing-to gait with both legs'],'C','In a three-point gait, both crutches and the affected leg move forward together, then the unaffected leg steps through, keeping weight off the injured leg.',PF),
  q(NEURO,'In constraint-induced movement therapy for a stroke survivor, what is done?','The stronger arm is restrained',['Both arms are immobilized','The weaker arm is rested in a sling','Only passive range of motion is performed'],'B','Restricting the unaffected arm overcomes learned non-use and promotes neuroplastic recovery of the affected arm.',PAG),
  q(NEURO,'A patient with a T4 spinal cord injury suddenly has a pounding headache and very high blood pressure during therapy. What should the PT do first?','Sit the patient up and find the trigger',['Lay the patient flat and continue exercise','Give the patient water and wait','Increase exercise intensity'],'D','This is autonomic dysreflexia, a medical emergency in injuries at T6 or above. Sitting upright lowers blood pressure, and the trigger (often bladder or bowel) must be removed.',PAG),
  q(NEURO,'A patient with Parkinson’s disease “freezes” when starting to walk. Which strategy often helps?','Visual or rhythmic cues',['Walking faster with shorter steps','Looking down at the feet while stepping','Holding the breath while stepping'],'A','External cues bypass the basal ganglia problems that impair automatic movement, helping patients start and continue walking.',PAG),
  q(NEURO,'Why should patients with multiple sclerosis avoid overheating during exercise?','Heat can worsen symptoms',['Heat cures the disease','Heat strengthens damaged nerves','Heat prevents fatigue'],'C','Higher body temperature slows conduction in demyelinated nerves (Uhthoff’s phenomenon). Cool environments and rest breaks help.',PAG),
  q(NEURO,'Which movement problem is most common in children with spastic cerebral palsy?','Increased muscle tone and stiffness',['Complete absence of muscle tone','Rapid, uncontrolled weight gain','Progressive muscle wasting'],'B','Spasticity is velocity-dependent resistance to stretch. PT focuses on stretching, strengthening, positioning and mobility.',PAG),
  q(NEURO,'Which scale describes stages of cognitive recovery after a traumatic brain injury?','Rancho scale',['Borg scale','Braden scale','Apgar scale'],'D','The Rancho scale describes levels from no response to purposeful, appropriate behavior, helping guide therapy approaches.',PAG),
  q(NEURO,'A patient develops weakness that begins in the legs and moves upward a few weeks after a viral illness. Which condition is likely?','Guillain-Barré',['Parkinson’s disease','Multiple sclerosis','Cerebral palsy'],'A','Guillain-Barré is an autoimmune attack on peripheral nerves, often after infection. Breathing may be affected, and recovery often needs rehab.',PAG),
  q(NEURO,'What is neuroplasticity?','The brain’s ability to rewire itself',['Permanent loss of brain function','Growth of new bone in the skull','Hardening of nerve tissue'],'C','Repetitive, task-specific practice drives neuroplasticity, which underlies recovery after stroke and brain injury.',PAG),
  q(CP,'Phase I cardiac rehabilitation takes place:','In the hospital',['At home after 6 months','Only at a gym','Before any heart problem occurs'],'B','Phase I is inpatient, with early mobility and education. Phase II is supervised outpatient rehab, and later phases focus on long-term maintenance.',PAG),
  q(CP,'On the Borg rating of perceived exertion scale (6–20), a rating of 13 means the patient feels:','Somewhat hard',['Extremely light','Very, very hard','Maximal effort'],'D','A rating around 12–14 is “somewhat hard,” a common target for moderate aerobic exercise in rehab.',PAG),
  q(CP,'Using the formula 220 − age, what is 70% of the estimated maximum heart rate for a 60-year-old?','112 beats per minute',['98 beats per minute','126 beats per minute','160 beats per minute'],'A','Estimated maximum = 220 − 60 = 160. 160 × 0.70 = 112 beats per minute. Beta blockers can blunt heart rate, so RPE is also used.',PAG),
  q(CP,'During exercise, which finding means the session should stop?','A fall in systolic pressure',['A modest rise in the heart rate','Mild sweating','Breathing a little faster'],'C','Blood pressure should rise with exercise. A fall, chest pain, dizziness or severe dyspnea suggests the heart is not tolerating the workload.',PAG),
  q(CP,'What does the 6-minute walk test measure?','Functional exercise capacity',['Lung volumes','Balance only','Muscle strength in one joint'],'B','The distance walked in 6 minutes reflects endurance in daily activities and is used in heart and lung disease.',PAG),
  q(CP,'After several days of bed rest, a patient becomes dizzy when first sitting up. What is the likely cause?','Orthostatic drop',['Hypertension','Hyperglycemia','Pulmonary embolism'],'D','Bed rest weakens the body’s blood pressure response to standing. Gradual position changes and monitoring vital signs help.',PF),
  q(CP,'Why should patients with heart disease avoid holding their breath while lifting?','It causes sharp blood pressure swings',['It improves oxygen delivery','It lowers the heart rate safely and quickly','It strengthens the diaphragm'],'A','Straining against a closed airway raises chest pressure, then causes rapid swings in blood pressure and heart rate. Patients are taught to exhale during effort.',PF),
  q(INTEG,'Which description fits an arterial ulcer?','A painful, pale wound on the toes with little drainage',['A shallow, heavily draining wound above the ankle','A wound over the sacrum from pressure','A wound with brown skin staining around it'],'C','Poor arterial flow causes painful, punched-out ulcers on the toes or feet. Venous ulcers usually occur near the medial ankle with heavy drainage.',PAG),
  q(INTEG,'Which treatment is central to healing venous leg ulcers?','Compression therapy',['Keeping the leg dangling down','Heat packs on the wound','Strict bed rest without elevation'],'B','Compression and leg elevation reduce venous pressure and swelling, helping venous ulcers heal. Compression is avoided if arterial flow is poor.',PAG),
  q(INTEG,'How is a stage 3 pressure injury described?','Full-thickness loss exposing fat only',['Intact skin with non-blanchable redness','Partial-thickness loss like a blister','Exposed bone, tendon or muscle'],'D','Stage 1 is intact red skin, stage 2 is partial-thickness loss, stage 3 is full-thickness loss into fat, and stage 4 exposes bone, tendon or muscle.',PAG),
  q(INTEG,'After a burn to the front of the neck, how is the patient positioned to prevent a contracture?','With the neck extended',['With the chin tucked to the chest','With the head turned fully to one side','With the neck flexed on pillows'],'A','Scars contract toward the position of comfort, usually flexion. Positioning and splinting in extension preserves motion.',PAG),
  q(INTEG,'Why are moist wound dressings used for most clean wounds?','A moist environment speeds healing',['They dry the wound quickly','They prevent all bacteria','They replace the need for cleaning'],'C','A moist (not wet) environment helps cells migrate and new tissue form. Letting wounds dry out slows healing.',PAG),
  q(INTEG,'A patient with diabetes has an ulcer on the bottom of the foot. Which treatment helps it heal?','Offloading pressure',['Walking barefoot to toughen the skin','Soaking the foot in hot water','Wearing tight, narrow shoes'],'B','Pressure from walking keeps diabetic foot ulcers from healing. Offloading devices redistribute pressure.',PAG),
  q(INTEG,'How is wound size usually measured for documentation?','Length × width × depth',['By the patient’s pain rating','By weight of the dressing','By the color of the skin only'],'D','Consistent measurements, along with tunneling, undermining and tissue type, show whether a wound is healing.',PAG),
  q(AGE,'At about what age do most children begin walking independently?','12 months',['6 months','24 months','36 months'],'A','Most children walk between about 9 and 15 months, around 12 months on average. Not walking by about 18 months warrants evaluation.',PAG),
  q(AGE,'An infant keeps the head tilted to one side and turned to the other because of a tight neck muscle. Which condition is this?','Torticollis',['Spina bifida','Down syndrome','Cerebral palsy'],'C','Tightness of the sternocleidomastoid causes the head tilt. Treatment includes stretching, positioning and tummy time.',PAG),
  q(AGE,'Children with Down syndrome often have which motor characteristic?','Low muscle tone (hypotonia)',['High muscle tone (spasticity)','Rigid joints','Excessive strength'],'B','Hypotonia and loose joints contribute to delayed motor milestones. PT supports strength and motor development.',PAG),
  q(AGE,'Which quick test of standing, walking 3 meters, turning and sitting helps screen older adults for fall risk?','Timed Up and Go',['6-minute walk test','Goniometry','Manual muscle test'],'D','Taking about 12–14 seconds or longer on the TUG suggests increased fall risk.',PAG),
  q(AGE,'Which exercise best counters sarcopenia in older adults?','Resistance training',['Only gentle stretching','Complete rest','Only slow walking'],'A','Resistance training builds muscle strength and mass at any age, improving function and reducing fall risk.',PAG),
  q(AGE,'Which movement should patients with osteoporosis generally avoid during exercise?','Loaded forward bending of the spine',['Walking on level ground','Extension exercises for the back','Balance training'],'C','Spinal flexion, especially with lifting, raises the risk of vertebral compression fractures. Extension and weight-bearing exercise are encouraged.',PAG),
  q(AGE,'Under the Individuals with Disabilities Education Act, which program serves children from birth to age 3?','Early intervention (Part C)',['School-based services (Part B)','Medicare','Section 504 only'],'B','Part C provides early intervention services, often in the home. Part B serves children aged 3–21 in schools.',PAG),
  q(AGE,'Which tool measures balance through 14 tasks and helps identify fall risk in older adults?','Berg scale',['Borg scale','Rancho scale','Braden scale'],'D','The Berg Balance Scale scores 14 balance tasks out of 56 points. Lower scores indicate higher fall risk.',PAG)
 ],101)
};
